    Environment = "prod"
    Owner       = "platform-team"
    Project     = "my-project"
  }
}

findings.recommendation:
Add `lifecycle { prevent_destroy = true }` to any resource that holds
irrecoverable state:

    resource "aws_dynamodb_table" "orders" {
      # ...
      lifecycle {
        prevent_destroy = true
      }
    }

The block forces operators to remove the line intentionally before a
destroy plan can succeed — a deliberate friction that prevents
accidental data loss on `terraform destroy` or workspace deletion.

